std::string ReadNamedKey(const char* key, const char* alternateKey)
{
  const char* value = 0;
  if (key)
  {
    value = CmdLineLite::Instance().GetStringKey(key, 0);
  }
  if ((!value || !value[0]) && alternateKey)
  {
    value = CmdLineLite::Instance().GetStringKey(alternateKey, 0);
  }
  return value ? value : "";
}

