void DeleteLinuxOverlayGlyphTextures(LinuxWindowOverlay* overlay)
{
  if (!overlay)
  {
    return;
  }

  for (std::map<unsigned long, LinuxWindowOverlay::OpenGlGlyph>::iterator it = overlay->fontGlyphs.begin();
       it != overlay->fontGlyphs.end();
       ++it)
  {
    if (it->second.texture)
    {
      glDeleteTextures(1, &it->second.texture);
      it->second.texture = 0;
    }
  }
  overlay->fontGlyphs.clear();
}

void ShutdownWindowOverlay(LinuxWindowOverlay* overlay)
{
  if (overlay->openglReady && NMainFrame::MakeOpenGLContextCurrent())
  {
    if (overlay->artworkTexture)
    {
      glDeleteTextures(1, &overlay->artworkTexture);
      overlay->artworkTexture = 0;
    }

    if (overlay->lobbyBackgroundTexture)
    {
      glDeleteTextures(1, &overlay->lobbyBackgroundTexture);
      overlay->lobbyBackgroundTexture = 0;
    }

    DeleteOpenGlTexture(&overlay->lobbyButtonUp);
    DeleteOpenGlTexture(&overlay->lobbyButtonOver);
    DeleteOpenGlTexture(&overlay->lobbyPanel);
    DeleteOpenGlTexture(&overlay->lobbyHeader);
    DeleteOpenGlTexture(&overlay->lobbyFrame);
    DeleteOpenGlTexture(&overlay->lobbySelectionFrame);
    DeleteOpenGlTexture(&overlay->lobbyRadioNormal);
    DeleteOpenGlTexture(&overlay->lobbyRadioSelected);
    DeleteOpenGlTexture(&overlay->lobbyScrollArea);
    DeleteOpenGlTexture(&overlay->lobbyScrollLever);
    DeleteOpenGlTexture(&overlay->lobbyScrollHorizontalFirst);
    DeleteOpenGlTexture(&overlay->lobbyScrollHorizontalSecond);
    DeleteOpenGlTexture(&overlay->lobbySelectedMapBack);
    DeleteOpenGlTexture(&overlay->lobbySelectedMapLogo);
    DeleteOpenGlTexture(&overlay->lobbySelectedMapMinimap);
    for (std::map<std::string, LinuxWindowOverlay::OpenGlTexture>::iterator it =
           overlay->lobbyTextureCache.begin();
         it != overlay->lobbyTextureCache.end();
         ++it)
    {
      DeleteOpenGlTexture(&it->second);
    }
    overlay->lobbyTextureCache.clear();
    overlay->lobbyTextureFailedSourceFiles.clear();
    for (std::map<std::string, LinuxWindowOverlay::OpenGlTexture>::iterator it =
           overlay->heroPreviewDiffuseTextureCache.begin();
         it != overlay->heroPreviewDiffuseTextureCache.end();
         ++it)
    {
      DeleteOpenGlTexture(&it->second);
    }
    overlay->heroPreviewDiffuseTextureCache.clear();
    for (size_t i = 0; i < overlay->heroPreviewDiffuseTextures.size(); ++i)
    {
      DeleteOpenGlTexture(&overlay->heroPreviewDiffuseTextures[i]);
    }
    overlay->heroPreviewDiffuseTextures.clear();
    overlay->heroPreviewDiffuseTextureSourceFiles.clear();
    overlay->heroPreviewDiffuseTextureFailedSourceFiles.clear();
    for (size_t i = 0; i < overlay->mapPreviewDiffuseTextures.size(); ++i)
    {
      DeleteOpenGlTexture(&overlay->mapPreviewDiffuseTextures[i]);
    }
    overlay->mapPreviewDiffuseTextures.clear();
    overlay->mapPreviewDiffuseTextureSourceFiles.clear();
    overlay->mapPreviewDiffuseTextureFailedSourceFiles.clear();
    DeleteLinuxOverlayGlyphTextures(overlay);

    if (overlay->fontDisplayListsReady && overlay->fontDisplayListBase != 0)
    {
      glDeleteLists(overlay->fontDisplayListBase, 256);
      overlay->fontDisplayListBase = 0;
      overlay->fontDisplayListsReady = false;
    }
  }

  if (overlay->ftFace)
  {
    FT_Done_Face(overlay->ftFace);
    overlay->ftFace = 0;
  }
  if (overlay->ftLibrary)
  {
    FT_Done_FreeType(overlay->ftLibrary);
    overlay->ftLibrary = 0;
  }
  overlay->freetypeReady = false;
  overlay->freetypePixelSize = 0;
  overlay->freetypeFontPath.clear();

  if (overlay->display && overlay->artworkPixmap)
  {
    XFreePixmap(overlay->display, overlay->artworkPixmap);
    overlay->artworkPixmap = 0;
  }

  if (overlay->display && overlay->gc)
  {
    XFreeGC(overlay->display, overlay->gc);
    overlay->gc = 0;
  }

  if (overlay->display && overlay->fontStruct)
  {
    XFreeFont(overlay->display, overlay->fontStruct);
    overlay->fontStruct = nullptr;
  }

  overlay->display = nullptr;
  overlay->window = 0;
  overlay->artworkWidth = 0;
  overlay->artworkHeight = 0;
  overlay->openglReady = false;
  overlay->ready = false;
}

std::string DescribeInputEvent(const Input::Event& event)
{
  char buffer[256] = {0};
  const char* name = event.Command() ? event.Command()->Name().c_str() : "<null>";

  switch (event.Type())
  {
    case Input::EEventType::Activation:
      snprintf(buffer, sizeof(buffer), "%s activated", name);
      break;

    case Input::EEventType::ScalarDelta:
      snprintf(buffer, sizeof(buffer), "%s delta=%.2f", name, event.Delta());
      break;

    case Input::EEventType::ScalarValue:
      snprintf(buffer, sizeof(buffer), "%s value=%.2f", name, event.Value());
      break;

    case Input::EEventType::System:
      snprintf(
        buffer,
        sizeof(buffer),
        "%s a=%d b=%d",
        name,
        event.SysParams().first,
        event.SysParams().second
      );
      break;

    default:
      snprintf(buffer, sizeof(buffer), "%s", name);
      break;
  }

  return std::string(buffer);
}

void DrainMainFrameMessages(TLinuxMainFrameMessages* messages)
{
  messages->clear();

  NMainFrame::SWindowsMsg message;
  while (NMainFrame::GetMessage(&message))
  {
    messages->push_back(message);
  }
}

void UpdateInputState(LinuxInputState* state)
{
  state->frameEvents.clear();
  state->rawMessages.clear();
  DrainMainFrameMessages(&state->rawMessages);

  if (!state->initialized || !IsValid(state->hwInput) || !IsValid(state->binds))
  {
    return;
  }

  state->hwInput->SetFrameMessages(state->rawMessages);

  NHPTimer::STime now = 0;
  NHPTimer::GetTime(now);
  float deltaSeconds = state->lastUpdateTime ? NHPTimer::Time2Seconds(now - state->lastUpdateTime) : (1.0f / 60.0f);
  if (deltaSeconds <= 0.0f)
  {
    deltaSeconds = 1.0f / 60.0f;
  }
  state->lastUpdateTime = now;
  state->lastDeltaSeconds = deltaSeconds;

  state->binds->Update(deltaSeconds, NMainFrame::IsAppActive());

  vector<Input::Event>& bindEvents = state->binds->GetEvents();
  for (int i = 0; i < bindEvents.size(); ++i)
  {
    state->frameEvents.push_back(bindEvents[i]);
  }

  state->totalEvents += state->frameEvents.size();

  for (size_t i = 0; i < state->frameEvents.size(); ++i)
  {
    const Input::Event& event = state->frameEvents[i];
    if (RunLinuxCommandBinding(event))
    {
      ++state->commandBindingHits;
    }

    state->recentEvents.push_back(DescribeInputEvent(event));
  }

  state->binds->ClearEvents();

  const size_t maxRecentEvents = 6;
  if (state->recentEvents.size() > maxRecentEvents)
  {
    state->recentEvents.erase(state->recentEvents.begin(), state->recentEvents.end() - maxRecentEvents);
  }
}

void DriveLinuxUiUser(
  const LinuxInputState& inputState,
  LinuxUiRootPreview* preview
)
{
  if (!preview)
  {
    return;
  }

  UI::User* user = UI::GetUser();
  preview->runtimeUserReady = user != 0;
  if (!user)
  {
    preview->runtimeUserPath = "inactive";
    return;
  }

  preview->runtimeUserPath = "UI::User::StartEvent/EndEvent/Step";

  for (size_t i = 0; i < inputState.frameEvents.size(); ++i)
  {
    user->StartEvent(inputState.frameEvents[i]);
  }

  for (size_t i = 0; i < inputState.frameEvents.size(); ++i)
  {
    user->EndEvent(inputState.frameEvents[i]);
  }

  user->Step(inputState.lastDeltaSeconds);
  preview->runtimeUserEventCount += inputState.frameEvents.size();
}

unsigned long GetLinuxTickMs()
{
  NHPTimer::STime now = 0;
  NHPTimer::GetTime(now);
  return static_cast<unsigned long>(NHPTimer::Time2Milliseconds(now));
}

void DriveLinuxUiCursor(
  LinuxUiRootPreview* preview
)
{
  if (!preview || !preview->runtimeInitialized)
  {
    return;
  }

  preview->runtimeCursorReady = false;
  preview->runtimeCursorRegistered = false;
  preview->runtimeCursorId.clear();
  preview->runtimeCursorWidth = 0;
  preview->runtimeCursorHeight = 0;
  preview->runtimeCursorHotspotX = 0;
  preview->runtimeCursorHotspotY = 0;

  static const char* cursorCandidates[] = { "ui_normal", "default" };
  for (size_t i = 0; i < sizeof(cursorCandidates) / sizeof(cursorCandidates[0]); ++i)
  {
    if (NCursors::IsRegistered(cursorCandidates[i]))
    {
      preview->runtimeCursorRegistered = true;
      preview->runtimeCursorId = cursorCandidates[i];
      break;
    }
  }

  if (!preview->runtimeCursorRegistered)
  {
    preview->runtimeCursorPath = "no-registered-cursor";
    return;
  }

  UI::SetCursor(preview->runtimeCursorId.c_str());
  NCursor::Update(GetLinuxTickMs());

  const UI::Point& cursorSize = NCursor::GetCurrentSize();
  const UI::Point& cursorHotspot = NCursor::GetCurrentHotSpot();
  preview->runtimeCursorWidth = cursorSize.x;
  preview->runtimeCursorHeight = cursorSize.y;
  preview->runtimeCursorHotspotX = cursorHotspot.x;
  preview->runtimeCursorHotspotY = cursorHotspot.y;
  preview->runtimeCursorReady = (cursorSize.x > 0) && (cursorSize.y > 0);
  preview->runtimeCursorPath = "UI::SetCursor/NCursor::Update";
}

bool IsLinuxBootstrapLoadingScreenActive(const LinuxBootstrapScreenRuntime* runtime)
{
  return runtime &&
    runtime->loadingInitialized &&
    IsValid(runtime->loadingScreen);
}

bool IsLinuxBootstrapHeroScreenActive(const LinuxBootstrapScreenRuntime* runtime)
{
  return runtime &&
    !IsLinuxBootstrapLoadingScreenActive(runtime) &&
    runtime->heroInitialized &&
    IsValid(runtime->heroScreen) &&
    IsValid(runtime->gameContext) &&
    runtime->gameContext->GetLobbyStatus() == lobby::EClientStatus::InCustomLobby;
}

const char* DescribeLinuxBootstrapReadyState(lobby::EGameMemberReadiness::Enum readiness)
{
  switch (readiness)
  {
    case lobby::EGameMemberReadiness::Ready:
      return "ready";

    case lobby::EGameMemberReadiness::ReadyForAnything:
      return "ready-for-anything";

    default:
      return "not-ready";
  }
}

bool IsLinuxDiagnosticsOverlayActive(
  const LinuxClientLaunchSettings& settings,
  const LinuxBootstrapScreenRuntime* runtime
)
{
  return settings.diagnosticsOverlay || (runtime && runtime->diagnosticsOverlayActive);
}

bool IsLinuxVisibleMenuActive(
  const LinuxClientLaunchSettings& settings,
  const LinuxBootstrapScreenRuntime* runtime
)
{
  return runtime &&
    runtime->visibleMenuReady &&
    !IsLinuxBootstrapLoadingScreenActive(runtime) &&
    !IsLinuxDiagnosticsOverlayActive(settings, runtime);
}

struct LinuxScreenRect
{
  int x;
  int y;
  int width;
  int height;

  LinuxScreenRect()
    : x(0),
      y(0),
      width(0),
      height(0)
  {
  }
};

LinuxScreenRect MakeLinuxScreenRect(int x, int y, int width, int height)
{
  LinuxScreenRect rect;
  rect.x = x;
  rect.y = y;
  rect.width = width;
  rect.height = height;
  return rect;
}

LinuxScreenRect ResolveLinuxCharacterPreviewRect(
  int screenWidth,
  int screenHeight,
  bool loadingActive
)
{
  LinuxScreenRect rect;
  if (screenWidth <= 0 || screenHeight <= 0)
  {
    return rect;
  }

  if (loadingActive)
  {
    rect.width = std::min(320, std::max(240, screenWidth / 4));
    rect.height = std::min(260, std::max(190, screenHeight / 3));
    rect.x = std::max(16, screenWidth - rect.width - 42);
    rect.y = std::max(64, screenHeight - rect.height - 62);
    return rect;
  }

  rect.width = std::min(380, std::max(280, screenWidth / 3));
  rect.height = std::min(260, std::max(190, screenHeight / 3));
  rect.x = std::max(16, screenWidth - rect.width - 74);
  rect.y = std::max(58, screenHeight / 11);
  return rect;
}

bool IsPointInsideLinuxScreenRect(const LinuxScreenRect& rect, int x, int y)
{
  return rect.width > 0 &&
    rect.height > 0 &&
    x >= rect.x &&
    y >= rect.y &&
    x < rect.x + rect.width &&
    y < rect.y + rect.height;
}

bool IsPointInsideLinuxRectValues(
  int rectX,
  int rectY,
  int rectWidth,
  int rectHeight,
  int x,
  int y
)
{
  return rectWidth > 0 &&
    rectHeight > 0 &&
    x >= rectX &&
    y >= rectY &&
    x < rectX + rectWidth &&
    y < rectY + rectHeight;
}

