void StoreLinuxLiveHudTalentCommandSurface(
  LinuxBootstrapScreenRuntime* runtime,
  int x,
  int y,
  int width,
  int height,
  int talentLevel,
  int talentSlot
)
{
  if (!runtime ||
      width <= 0 ||
      height <= 0 ||
      runtime->liveHudTalentCommandSlots >= LINUX_LIVE_HUD_MAX_TALENT_COMMAND_SLOTS)
  {
    return;
  }

  const size_t index = runtime->liveHudTalentCommandSlots++;
  runtime->liveHudTalentX[index] = x;
  runtime->liveHudTalentY[index] = y;
  runtime->liveHudTalentWidth[index] = width;
  runtime->liveHudTalentHeight[index] = height;
  runtime->liveHudTalentLevel[index] = talentLevel;
  runtime->liveHudTalentSlot[index] = talentSlot;
  runtime->liveHudCommandSurfaceReady = true;
}

int FindLinuxLiveHudTalentCommandSlot(
  const LinuxBootstrapScreenRuntime* runtime,
  int x,
  int y
)
{
  if (!runtime)
  {
    return -1;
  }

  const size_t slotCount =
    std::min(runtime->liveHudTalentCommandSlots, LINUX_LIVE_HUD_MAX_TALENT_COMMAND_SLOTS);
  for (size_t i = 0; i < slotCount; ++i)
  {
    if (IsPointInsideLinuxRectValues(
          runtime->liveHudTalentX[i],
          runtime->liveHudTalentY[i],
          runtime->liveHudTalentWidth[i],
          runtime->liveHudTalentHeight[i],
          x,
          y))
    {
      return static_cast<int>(i);
    }
  }

  return -1;
}

bool IsPointInsideLinuxLiveHudCommandSurface(
  const LinuxBootstrapScreenRuntime* runtime,
  int x,
  int y
)
{
  if (!runtime || !runtime->liveHudCommandSurfaceReady)
  {
    return false;
  }

  return IsPointInsideLinuxRectValues(
      runtime->liveHudAttackX,
      runtime->liveHudAttackY,
      runtime->liveHudAttackWidth,
      runtime->liveHudAttackHeight,
      x,
      y) ||
    IsPointInsideLinuxRectValues(
      runtime->liveHudTargetX,
      runtime->liveHudTargetY,
      runtime->liveHudTargetWidth,
      runtime->liveHudTargetHeight,
      x,
      y) ||
    FindLinuxLiveHudTalentCommandSlot(runtime, x, y) >= 0;
}

struct LinuxLiveMinimapLayout
{
  bool ready;
  int panelX;
  int panelY;
  int mapSize;
  int panelHeight;
  int innerX;
  int innerY;
  int innerSize;
  float minX;
  float maxX;
  float minY;
  float maxY;

  LinuxLiveMinimapLayout()
    : ready(false),
      panelX(0),
      panelY(0),
      mapSize(0),
      panelHeight(0),
      innerX(0),
      innerY(0),
      innerSize(0),
      minX(0.0f),
      maxX(0.0f),
      minY(0.0f),
      maxY(0.0f)
  {
  }
};

LinuxLiveMinimapLayout ResolveLinuxLiveMinimapLayout(
  int screenWidth,
  int screenHeight,
  bool loadingActive,
  const LinuxSelectedMapPreview* selectedMapPreview
)
{
  LinuxLiveMinimapLayout layout;
  if (screenWidth <= 0 ||
      screenHeight <= 0 ||
      !selectedMapPreview ||
      !selectedMapPreview->tactical.ready)
  {
    return layout;
  }

  layout.mapSize = loadingActive ?
    std::max(128, std::min(150, screenWidth / 8)) :
    std::max(168, std::min(236, screenWidth / 6));
  const int padding = 8;
  layout.panelX = std::max(14, screenWidth - layout.mapSize - 24);
  layout.panelY = 42;
  if (loadingActive)
  {
    const int rosterH = std::max(150, std::min(188, screenHeight / 4 + 8));
    const int rosterY = std::max(64, screenHeight - rosterH - 48);
    const int chatY = std::max(164, std::min(186, rosterY - 188));
    const int chatH = std::max(96, std::min(176, rosterY - chatY - 12));
    layout.panelX = 42;
    layout.panelY = std::max(
      chatY + chatH + 8,
      std::min(rosterY - layout.mapSize - 12, screenHeight - layout.mapSize - 46));
  }
  layout.panelY = std::max(
    38,
    std::min(layout.panelY, std::max(38, screenHeight - layout.mapSize - 46)));
  layout.innerX = layout.panelX + padding;
  layout.innerY = layout.panelY + padding + 18;
  layout.innerSize = std::max(1, layout.mapSize - padding * 2);
  layout.panelHeight = layout.innerSize + padding * 2 + 32;
  layout.minX = selectedMapPreview->tactical.minX;
  layout.maxX = selectedMapPreview->tactical.maxX;
  layout.minY = selectedMapPreview->tactical.minY;
  layout.maxY = selectedMapPreview->tactical.maxY;
  layout.ready = true;
  return layout;
}

void StoreLinuxLiveMinimapCommandSurface(
  LinuxBootstrapScreenRuntime* runtime,
  const LinuxLiveMinimapLayout& layout
)
{
  if (!runtime)
  {
    return;
  }

  runtime->liveMinimapCommandSurfaceReady = layout.ready;
  runtime->liveMinimapInnerX = layout.innerX;
  runtime->liveMinimapInnerY = layout.innerY;
  runtime->liveMinimapInnerSize = layout.innerSize;
  runtime->liveMinimapMinX = layout.minX;
  runtime->liveMinimapMaxX = layout.maxX;
  runtime->liveMinimapMinY = layout.minY;
  runtime->liveMinimapMaxY = layout.maxY;
}

void ClearLinuxLiveMinimapCommandSurface(LinuxBootstrapScreenRuntime* runtime)
{
  if (!runtime)
  {
    return;
  }

  runtime->liveMinimapCommandSurfaceReady = false;
  runtime->liveMinimapInnerX = 0;
  runtime->liveMinimapInnerY = 0;
  runtime->liveMinimapInnerSize = 0;
  runtime->liveMinimapMinX = 0.0f;
  runtime->liveMinimapMaxX = 0.0f;
  runtime->liveMinimapMinY = 0.0f;
  runtime->liveMinimapMaxY = 0.0f;
}

bool ProjectLinuxLiveMinimapScreenToWorld(
  const LinuxBootstrapScreenRuntime& runtime,
  int mouseX,
  int mouseY,
  float* worldX,
  float* worldY
)
{
  if (worldX) *worldX = 0.0f;
  if (worldY) *worldY = 0.0f;
  if (!runtime.liveMinimapCommandSurfaceReady || runtime.liveMinimapInnerSize <= 0)
  {
    return false;
  }

  const int innerX = runtime.liveMinimapInnerX;
  const int innerY = runtime.liveMinimapInnerY;
  const int innerSize = runtime.liveMinimapInnerSize;
  if (mouseX < innerX ||
      mouseY < innerY ||
      mouseX >= innerX + innerSize ||
      mouseY >= innerY + innerSize)
  {
    return false;
  }

  const float rangeX = std::max(1.0f, runtime.liveMinimapMaxX - runtime.liveMinimapMinX);
  const float rangeY = std::max(1.0f, runtime.liveMinimapMaxY - runtime.liveMinimapMinY);
  const float normalizedX =
    static_cast<float>(mouseX - innerX) / static_cast<float>(std::max(1, innerSize - 1));
  const float normalizedY =
    1.0f - static_cast<float>(mouseY - innerY) / static_cast<float>(std::max(1, innerSize - 1));
  const float projectedX = runtime.liveMinimapMinX + std::max(0.0f, std::min(1.0f, normalizedX)) * rangeX;
  const float projectedY = runtime.liveMinimapMinY + std::max(0.0f, std::min(1.0f, normalizedY)) * rangeY;

  if (worldX) *worldX = projectedX;
  if (worldY) *worldY = projectedY;
  return true;
}

bool ProjectLinuxLiveMinimapWorldToScreen(
  const LinuxBootstrapScreenRuntime& runtime,
  const CVec2& worldPosition,
  int* screenX,
  int* screenY
)
{
  if (screenX) *screenX = 0;
  if (screenY) *screenY = 0;
  if (!runtime.liveMinimapCommandSurfaceReady || runtime.liveMinimapInnerSize <= 0)
  {
    return false;
  }

  const float rangeX = std::max(1.0f, runtime.liveMinimapMaxX - runtime.liveMinimapMinX);
  const float rangeY = std::max(1.0f, runtime.liveMinimapMaxY - runtime.liveMinimapMinY);
  const float normalizedX =
    std::max(0.0f, std::min(1.0f, (worldPosition.x - runtime.liveMinimapMinX) / rangeX));
  const float normalizedY =
    std::max(0.0f, std::min(1.0f, (worldPosition.y - runtime.liveMinimapMinY) / rangeY));
  if (screenX)
  {
    *screenX = runtime.liveMinimapInnerX +
      static_cast<int>(normalizedX * static_cast<float>(runtime.liveMinimapInnerSize - 1));
  }
  if (screenY)
  {
    *screenY = runtime.liveMinimapInnerY + runtime.liveMinimapInnerSize -
      1 - static_cast<int>(normalizedY * static_cast<float>(runtime.liveMinimapInnerSize - 1));
  }
  return true;
}

void NormalizeLinuxCharacterPreviewYaw(LinuxBootstrapScreenRuntime* runtime)
{
  if (!runtime)
  {
    return;
  }

  while (runtime->characterPreviewYawDegrees < 0.0f)
  {
    runtime->characterPreviewYawDegrees += 360.0f;
  }
  while (runtime->characterPreviewYawDegrees >= 360.0f)
  {
    runtime->characterPreviewYawDegrees -= 360.0f;
  }
}

void RotateLinuxCharacterPreview(
  LinuxBootstrapScreenRuntime* runtime,
  float deltaDegrees,
  const char* action
)
{
  if (!runtime || deltaDegrees == 0.0f)
  {
    return;
  }

  runtime->characterPreviewYawDegrees += deltaDegrees;
  NormalizeLinuxCharacterPreviewYaw(runtime);
  runtime->characterPreviewLastAction = action ? action : "rotate";
  ++runtime->characterPreviewInputCount;
}

void NormalizeLinuxMapPreviewYaw(LinuxBootstrapScreenRuntime* runtime)
{
  if (!runtime)
  {
    return;
  }

  while (runtime->mapPreviewYawDegrees < 0.0f)
  {
    runtime->mapPreviewYawDegrees += 360.0f;
  }
  while (runtime->mapPreviewYawDegrees >= 360.0f)
  {
    runtime->mapPreviewYawDegrees -= 360.0f;
  }
}

void ClampLinuxMapPreviewCamera(LinuxBootstrapScreenRuntime* runtime)
{
  if (!runtime)
  {
    return;
  }

  runtime->mapPreviewPitchDegrees =
    std::max(35.0f, std::min(72.0f, runtime->mapPreviewPitchDegrees));
  runtime->mapPreviewZoom =
    std::max(0.55f, std::min(2.25f, runtime->mapPreviewZoom));
  runtime->mapPreviewPanX =
    std::max(-48.0f, std::min(48.0f, runtime->mapPreviewPanX));
  runtime->mapPreviewPanZ =
    std::max(-48.0f, std::min(48.0f, runtime->mapPreviewPanZ));
}

float NormalizeLinuxPreviewYawValue(float yawDegrees)
{
  while (yawDegrees < 0.0f)
  {
    yawDegrees += 360.0f;
  }
  while (yawDegrees >= 360.0f)
  {
    yawDegrees -= 360.0f;
  }
  return yawDegrees;
}

void RotateLinuxMapPreview(
  LinuxBootstrapScreenRuntime* runtime,
  float deltaDegrees,
  const char* action
)
{
  if (!runtime || deltaDegrees == 0.0f)
  {
    return;
  }

  runtime->mapPreviewYawDegrees += deltaDegrees;
  NormalizeLinuxMapPreviewYaw(runtime);
  runtime->mapPreviewLastAction = action ? action : "rotate";
  ++runtime->mapPreviewInputCount;
}

void ZoomLinuxMapPreview(
  LinuxBootstrapScreenRuntime* runtime,
  float scaleFactor,
  const char* action
)
{
  if (!runtime || scaleFactor <= 0.0f)
  {
    return;
  }

  runtime->mapPreviewZoom *= scaleFactor;
  ClampLinuxMapPreviewCamera(runtime);
  runtime->mapPreviewLastAction = action ? action : "zoom";
  ++runtime->mapPreviewInputCount;
}

void TiltLinuxMapPreview(
  LinuxBootstrapScreenRuntime* runtime,
  float deltaDegrees,
  const char* action
)
{
  if (!runtime || deltaDegrees == 0.0f)
  {
    return;
  }

  runtime->mapPreviewPitchDegrees += deltaDegrees;
  ClampLinuxMapPreviewCamera(runtime);
  runtime->mapPreviewLastAction = action ? action : "tilt";
  ++runtime->mapPreviewInputCount;
}

void PanLinuxMapPreview(
  LinuxBootstrapScreenRuntime* runtime,
  float deltaX,
  float deltaZ,
  const char* action
)
{
  if (!runtime || (deltaX == 0.0f && deltaZ == 0.0f))
  {
    return;
  }

  runtime->mapPreviewPanX += deltaX;
  runtime->mapPreviewPanZ += deltaZ;
  ClampLinuxMapPreviewCamera(runtime);
  runtime->mapPreviewLastAction = action ? action : "pan";
  ++runtime->mapPreviewInputCount;
}

void ResetLinuxMapPreviewCamera(LinuxBootstrapScreenRuntime* runtime, const char* action)
{
  if (!runtime)
  {
    return;
  }

  runtime->mapPreviewYawDegrees = kLinuxMapPreviewDefaultYawDegrees;
  runtime->mapPreviewPitchDegrees = kLinuxMapPreviewDefaultPitchDegrees;
  runtime->mapPreviewZoom = kLinuxMapPreviewDefaultZoom;
  runtime->mapPreviewPanX = 0.0f;
  runtime->mapPreviewPanZ = 0.0f;
  NormalizeLinuxMapPreviewYaw(runtime);
  ClampLinuxMapPreviewCamera(runtime);
  runtime->mapPreviewLastAction = action ? action : "reset";
  ++runtime->mapPreviewInputCount;
}

std::string DescribeLinuxVisibleMenuAction(
  const LinuxBootstrapScreenRuntime* runtime,
  size_t actionIndex
)
{
  switch (actionIndex)
  {
    case LINUX_VISIBLE_MENU_ACTION_PRIMARY:
      if (IsLinuxBootstrapLoadingScreenActive(runtime))
      {
        return "Loading";
      }
      if (runtime && IsValid(runtime->gameContext) &&
          runtime->gameContext->GetLobbyStatus() == lobby::EClientStatus::InCustomLobby)
      {
        return runtime->gameContext->GetReadyState() == lobby::EGameMemberReadiness::NotReady ?
          "Ready and load" :
          "Loading";
      }
      return "Create custom game";

    case LINUX_VISIBLE_MENU_ACTION_MAP:
      return "Cycle map";

    case LINUX_VISIBLE_MENU_ACTION_HERO:
      return "Cycle hero";

    case LINUX_VISIBLE_MENU_ACTION_DIAGNOSTICS:
      return runtime && runtime->diagnosticsOverlayActive ?
        "Hide diagnostics" :
        "Show diagnostics";

    default:
      return "<unknown>";
  }
}

const char* DescribeLinuxLobbyJoinMode(size_t joinMode)
{
  switch (joinMode)
  {
    case LINUX_LOBBY_JOIN_MODE_NORMAL:
      return "normal";

    case LINUX_LOBBY_JOIN_MODE_RECONNECT:
      return "reconnect";

    case LINUX_LOBBY_JOIN_MODE_SPECTATE:
      return "spectate";

    default:
      return "unknown";
  }
}

void UpdateLinuxVisibleMenuRuntime(LinuxBootstrapScreenRuntime* runtime)
{
  if (!runtime)
  {
    return;
  }

  runtime->visibleMenuReady = runtime->initialized && !IsLinuxBootstrapLoadingScreenActive(runtime);
  if (runtime->visibleMenuSelectedAction >= LINUX_VISIBLE_MENU_ACTION_COUNT)
  {
    runtime->visibleMenuSelectedAction = 0;
  }
  if (runtime->visibleLobbyJoinMode >= LINUX_LOBBY_JOIN_MODE_COUNT)
  {
    runtime->visibleLobbyJoinMode = LINUX_LOBBY_JOIN_MODE_NORMAL;
  }
  runtime->visibleMenuPath = runtime->visibleMenuReady ?
    "Linux visible lobby overlay + NGameX::SelectGameModeScreen" :
    "inactive";
}

int ResolveLinuxBootstrapCreateGamePlayers(
  const LinuxBootstrapScreenRuntime& runtime,
  const LinuxLocalMatchPreview& localMatchPreview
)
{
  if (IsValid(runtime.gameContext) && runtime.gameContext->GetMaxPlayers() > 0)
  {
    return runtime.gameContext->GetMaxPlayers();
  }

  const int requestedPlayers = localMatchPreview.requestedTeamSize > 0 ?
    localMatchPreview.requestedTeamSize * 2 :
    0;
  return requestedPlayers > 0 ? requestedPlayers : 10;
}

void MaybeRequestLinuxBootstrapCreateGame(
  const LinuxClientLaunchSettings& settings,
  const LinuxMapCatalog& mapCatalog,
  const LinuxMapBrowserState& mapBrowserState,
  const LinuxLocalMatchPreview& localMatchPreview,
  LinuxBootstrapScreenRuntime* runtime
)
{
  if (!settings.bootstrapCreateGame || !runtime || runtime->createGameRequested || !IsValid(runtime->gameContext))
  {
    return;
  }

  if (runtime->gameContext->GetLobbyStatus() == lobby::EClientStatus::InCustomLobby)
  {
    runtime->createGameRequested = true;
    return;
  }

  if (mapCatalog.entries.empty() || mapBrowserState.selectedIndex >= mapCatalog.entries.size())
  {
    return;
  }

  const std::string& descriptor = mapCatalog.entries[mapBrowserState.selectedIndex].descriptor;
  if (descriptor.empty())
  {
    return;
  }

  runtime->gameContext->CreateGame(
    descriptor.c_str(),
    ResolveLinuxBootstrapCreateGamePlayers(*runtime, localMatchPreview)
  );
  runtime->createGameRequested = true;
}

void BuildLinuxBootstrapHeroPlayerPreview(
  const LinuxHeroCatalog& heroCatalog,
  const LinuxLocalMatchPreview& localMatchPreview,
  const LinuxBootstrapGameContextUi& gameContext,
  vector<wstring>* lines,
  vector<int>* lineIds
)
{
  if (!lines || !lineIds)
  {
    return;
  }

  lines->clear();
  lineIds->clear();

  static const wchar_t* teamHeaders[] = { L"Doct:", L"Adornia:" };
  int botIndex = 1;

  for (int teamIndex = 0; teamIndex < 2; ++teamIndex)
  {
    const int team = teamIndex + 1;
    lines->push_back(teamHeaders[teamIndex]);
    lineIds->push_back(-1);

    for (size_t i = 0; i < localMatchPreview.lineup.size(); ++i)
    {
      const LinuxLocalMatchSlot& slot = localMatchPreview.lineup[i];
      int displayTeam = slot.team;
      std::string heroId = slot.heroId;
      std::string heroTitle = slot.heroTitle;
      const int selectedTeam = ConvertLobbyTeamSelectionToDisplayTeam(gameContext.GetSelectedTeam());

      if (slot.human && selectedTeam > 0)
      {
        displayTeam = selectedTeam;
      }

      if (slot.human && !gameContext.GetSelectedHeroId().empty())
      {
        heroId = gameContext.GetSelectedHeroId().c_str();
        const size_t heroIndex = FindHeroCatalogIndex(heroCatalog, heroId);
        if (heroIndex != static_cast<size_t>(-1))
        {
          const LinuxHeroCatalogEntry& heroEntry = heroCatalog.entries[heroIndex];
          heroId = ResolveHeroCatalogId(heroEntry);
          heroTitle = heroEntry.title;
        }
      }

      if (displayTeam != team)
      {
        continue;
      }

      const string nickname = slot.human ?
        string("Linux Player") :
        NStr::StrFmt("Bot %d", botIndex++);
      const bool ready = slot.human ?
        gameContext.GetReadyState() != lobby::EGameMemberReadiness::NotReady :
        true;
      const string heroTitleText = (heroTitle.empty() ? heroId : heroTitle).c_str();
      const wstring nicknameW = NStr::ToUnicode(nickname);
      const wstring heroTitleW = NStr::ToUnicode(heroTitleText);
      const wchar_t* readyText = ready ? L"<style:green>ready</style>" : L"<style:money>not ready</style>";

      lines->push_back(NStr::StrFmtW(
        L"<space:2>%s as %s, %s",
        nicknameW.c_str(),
        heroTitleW.c_str(),
        readyText
      ));
      lineIds->push_back(slot.human ? 1 : 100 + static_cast<int>(i));
    }
  }
}

void SyncLinuxBootstrapHeroScreenSelection(
  const LinuxHeroCatalog& heroCatalog,
  const LinuxLocalMatchPreview& localMatchPreview,
  LinuxBootstrapScreenRuntime* runtime
)
{
  if (!runtime || !IsValid(runtime->gameContext))
  {
    return;
  }

  if (runtime->gameContext->GetLobbyStatus() != lobby::EClientStatus::InCustomLobby)
  {
    return;
  }

  const int desiredTeam = localMatchPreview.humanTeam;
  if (desiredTeam != 1 && desiredTeam != 2)
  {
    return;
  }

  const int currentTeam = ConvertLobbyTeamSelectionToDisplayTeam(runtime->gameContext->GetSelectedTeam());
  const int currentFaction = ConvertLobbyTeamSelectionToDisplayTeam(runtime->gameContext->GetSelectedFaction());
  int desiredFaction = currentFaction;
  if (desiredFaction == 0 || desiredFaction == currentTeam)
  {
    desiredFaction = desiredTeam;
  }

  const string desiredHeroId = ResolveLinuxBootstrapSelectedHeroId(heroCatalog, localMatchPreview);
  const string& currentHeroId = runtime->gameContext->GetSelectedHeroId();

  const bool teamChanged = currentTeam != desiredTeam;
  const bool factionChanged = currentFaction != desiredFaction;
  const bool heroChanged = !desiredHeroId.empty() && currentHeroId != desiredHeroId;
  if (!teamChanged && !factionChanged && !heroChanged)
  {
    return;
  }

  runtime->gameContext->ChangeCustomGameSettings(
    teamChanged ? ConvertDisplayTeamToLobbyTeam(desiredTeam) : static_cast<lobby::ETeam::Enum>(-1),
    factionChanged ? ConvertDisplayTeamToLobbyTeam(desiredFaction) : static_cast<lobby::ETeam::Enum>(-1),
    heroChanged ? desiredHeroId : string()
  );
}

void MaybeAutoReadyLinuxBootstrapCreateGame(
  const LinuxClientLaunchSettings& settings,
  LinuxBootstrapScreenRuntime* runtime
)
{
  if (!settings.bootstrapCreateGame || !runtime || !IsValid(runtime->gameContext))
  {
    return;
  }

  if (runtime->gameContext->GetLobbyStatus() != lobby::EClientStatus::InCustomLobby)
  {
    return;
  }

  if (runtime->gameContext->GetReadyState() != lobby::EGameMemberReadiness::NotReady)
  {
    return;
  }

  if (runtime->gameContext->GetSelectedHeroId().empty())
  {
    return;
  }

  runtime->gameContext->SetReady(lobby::EGameMemberReadiness::ReadyForAnything);
}

bool HandleLinuxBootstrapHeroScreenHotkeys(
  const LinuxInputState& inputState,
  LinuxBootstrapScreenRuntime* runtime
)
{
  if (!IsLinuxBootstrapHeroScreenActive(runtime))
  {
    return false;
  }

  bool changed = false;
  for (size_t i = 0; i < inputState.rawMessages.size(); ++i)
  {
    const NMainFrame::SWindowsMsg& message = inputState.rawMessages[i];
    if (message.msg != NMainFrame::SWindowsMsg::KEY_DOWN)
    {
      continue;
    }

    switch (message.nKey)
    {
      case XK_f:
      case XK_F:
      {
        int currentFaction = ConvertLobbyTeamSelectionToDisplayTeam(runtime->gameContext->GetSelectedFaction());
        if (currentFaction == 0)
        {
          currentFaction = ConvertLobbyTeamSelectionToDisplayTeam(runtime->gameContext->GetSelectedTeam());
        }

        const int nextFaction = currentFaction == 2 ? 1 : 2;
        runtime->gameContext->ChangeCustomGameSettings(
          static_cast<lobby::ETeam::Enum>(-1),
          ConvertDisplayTeamToLobbyTeam(nextFaction),
          string()
        );
        changed = true;
        break;
      }

      case XK_r:
      case XK_R:
      {
        const lobby::EGameMemberReadiness::Enum currentReadyState = runtime->gameContext->GetReadyState();
        runtime->gameContext->SetReady(
          currentReadyState == lobby::EGameMemberReadiness::NotReady ?
            lobby::EGameMemberReadiness::ReadyForAnything :
            lobby::EGameMemberReadiness::NotReady
        );
        changed = true;
        break;
      }

      default:
        break;
    }
  }

  return changed;
}

void UpdateLinuxBootstrapHeroScreenPreview(
  const LinuxBootstrapScreenRuntime& runtime,
  LinuxUiRootPreview* preview
)
{
  if (!preview)
  {
    return;
  }

  preview->runtimeHeroScreenReady = IsLinuxBootstrapHeroScreenActive(&runtime);
  preview->runtimeHeroScreenWindowReady = false;
  preview->runtimeHeroPlayersReady = false;
  preview->runtimeHeroSelectionReady = false;
  preview->runtimeHeroReady = false;
  preview->runtimeHeroPlayerEntryCount = runtime.heroPlayerEntryCount;
  preview->runtimeHeroSelectedTeam = 0;
  preview->runtimeHeroSelectedFaction = 0;
  preview->runtimeHeroSelectedHeroId.clear();
  preview->runtimeHeroScreenWindow.clear();
  preview->runtimeHeroPlayersText = runtime.heroPlayersText;
  preview->runtimeHeroScreenPath = preview->runtimeHeroScreenReady ?
    "NGameX::SelectHeroScreen::Init/CommonStep/Draw" :
    "inactive";

  if (!preview->runtimeHeroScreenReady)
  {
    return;
  }

  preview->runtimeHeroSelectionReady = IsValid(runtime.gameContext);
  if (preview->runtimeHeroSelectionReady)
  {
    preview->runtimeHeroSelectedTeam = ConvertLobbyTeamSelectionToDisplayTeam(runtime.gameContext->GetSelectedTeam());
    preview->runtimeHeroSelectedFaction = ConvertLobbyTeamSelectionToDisplayTeam(runtime.gameContext->GetSelectedFaction());
    preview->runtimeHeroReady = runtime.gameContext->GetReadyState() != lobby::EGameMemberReadiness::NotReady;
    preview->runtimeHeroSelectedHeroId = runtime.gameContext->GetSelectedHeroId().c_str();
  }

  UI::Window* mainWindow = runtime.heroScreen->GetMainWindow();
  preview->runtimeHeroScreenWindowReady = mainWindow != 0;
  if (!mainWindow)
  {
    preview->runtimeHeroScreenWindow = "<no-window>";
    return;
  }

  const string& windowName = mainWindow->GetWindowName();
  if (!windowName.empty())
  {
    preview->runtimeHeroScreenWindow = windowName.c_str();
  }
  else
  {
    char unnamedWindow[64] = {0};
    snprintf(
      unnamedWindow,
      sizeof(unnamedWindow),
      "<unnamed:%d-children>",
      mainWindow->GetChildrenCount()
    );
    preview->runtimeHeroScreenWindow = unnamedWindow;
  }

  UI::Window* debugPlayersWindow = mainWindow->FindChild("DebugPlayers");
  UI::ImageLabel* debugPlayersLabel = debugPlayersWindow ?
    dynamic_cast<UI::ImageLabel*>(debugPlayersWindow) :
    0;
  preview->runtimeHeroPlayersReady = debugPlayersLabel != 0;
  if (debugPlayersLabel && preview->runtimeHeroPlayersText.empty())
  {
    const string caption = debugPlayersLabel->GetCaptionText();
    if (!caption.empty())
    {
      preview->runtimeHeroPlayersText = caption.c_str();
    }
  }
}

void UpdateLinuxBootstrapLoadingScreenPreview(
  const LinuxLoadingUiPreview& loadingUiPreview,
  const LinuxBootstrapScreenRuntime& runtime,
  LinuxUiRootPreview* preview
)
{
  if (!preview)
  {
    return;
  }

  preview->runtimeLoadingScreenReady = IsLinuxBootstrapLoadingScreenActive(&runtime);
  preview->runtimeLoadingScreenWindowReady = false;
  preview->runtimeLoadingStatusReady = false;
  preview->runtimeLoadingProgress = runtime.loadingProgressValue;
  preview->runtimeLoadingPlayerEntryCount = runtime.loadingPlayerEntryCount;
  preview->runtimeLoadingDisconnectedCount = runtime.loadingDisconnectedCount;
  preview->runtimeLoadingScreenWindow.clear();
  preview->runtimeLoadingStatusText = runtime.loadingStatusText;
  preview->runtimeLoadingScreenPath = preview->runtimeLoadingScreenReady ?
    (runtime.mapLoadingJob ?
      "Game::LoadingScreen::Init/Step/Draw + NWorld::MapLoadingJob::DoTheJob/PFWorld::LoadMap/TileMap::Prepare" :
      "Game::LoadingScreen::Init/Step/Draw") :
    "inactive";

  if (!preview->runtimeLoadingScreenReady)
  {
    return;
  }

  UI::Window* mainWindow = runtime.loadingScreen->GetMainWindow();
  preview->runtimeLoadingScreenWindowReady = mainWindow != 0;
  if (!mainWindow)
  {
    preview->runtimeLoadingScreenWindow = "<no-window>";
  }
  else
  {
    const string& windowName = mainWindow->GetWindowName();
    if (!windowName.empty())
    {
      preview->runtimeLoadingScreenWindow = windowName.c_str();
    }
    else
    {
      char unnamedWindow[64] = {0};
      snprintf(
        unnamedWindow,
        sizeof(unnamedWindow),
        "<unnamed:%d-children>",
        mainWindow->GetChildrenCount()
      );
      preview->runtimeLoadingScreenWindow = unnamedWindow;
    }
  }

  Game::LoadingScreenLogic* loadingLogic =
    dynamic_cast<Game::LoadingScreenLogic*>(runtime.loadingScreen->GetLogic());
  if (!loadingLogic || !loadingLogic->GetLoadingFlashInterface())
  {
    return;
  }

  const Game::LoadingFlashInterface* flashInterface = loadingLogic->GetLoadingFlashInterface();
  const vector<Game::LoadingFlashHeroState>& heroes = flashInterface->GetHeroes();
  preview->runtimeLoadingPlayerEntryCount = heroes.size();

  if (!heroes.empty())
  {
    float accumulatedProgress = 0.0f;
    size_t disconnectedCount = 0;
    for (size_t i = 0; i < heroes.size(); ++i)
    {
      accumulatedProgress += heroes[i].loadProgress / 100.0f;
      if (heroes[i].isLeftGame)
      {
        ++disconnectedCount;
      }
    }

    preview->runtimeLoadingProgress =
      std::max(preview->runtimeLoadingProgress, accumulatedProgress / static_cast<float>(heroes.size()));
    preview->runtimeLoadingDisconnectedCount = disconnectedCount;
  }

  std::string loadingStatusText = SanitizeLocalizedText(
    std::string(NStr::ToMBCS(flashInterface->GetLoadingStatusText()).c_str()));
  const NGameX::LoadingStatusHandler* loadingStatusHandler =
    runtime.loadingScreen->GetLoadingStatusHandler();
  if ((loadingStatusText.empty() || loadingStatusText == "{") && loadingStatusHandler)
  {
    const std::string statusKey = ToStdString(loadingStatusHandler->GetLastStatusId());
    const size_t statusIndex = statusKey.empty() ?
      static_cast<size_t>(-1) :
      FindLoadingStatusIndex(loadingUiPreview, statusKey.c_str());
    if (statusIndex != static_cast<size_t>(-1) &&
        statusIndex < loadingUiPreview.statuses.size() &&
        !loadingUiPreview.statuses[statusIndex].text.empty())
    {
      loadingStatusText = loadingUiPreview.statuses[statusIndex].text;
    }
    else
    {
      loadingStatusText = SanitizeLocalizedText(
        std::string(NStr::ToMBCS(loadingStatusHandler->GetCurrentStatusText()).c_str()));
    }
  }
  if (loadingStatusText.size() > 2 &&
      loadingStatusText[0] == '{' &&
      loadingStatusText[loadingStatusText.size() - 1] == '}')
  {
    const std::string fallbackStatusKey =
      loadingStatusText.substr(1, loadingStatusText.size() - 2);
    const size_t fallbackStatusIndex = FindLoadingStatusIndex(
      loadingUiPreview,
      fallbackStatusKey.c_str());
    if (fallbackStatusIndex != static_cast<size_t>(-1) &&
        fallbackStatusIndex < loadingUiPreview.statuses.size() &&
        !loadingUiPreview.statuses[fallbackStatusIndex].text.empty())
    {
      loadingStatusText = loadingUiPreview.statuses[fallbackStatusIndex].text;
    }
  }
  preview->runtimeLoadingStatusText = loadingStatusText;
  preview->runtimeLoadingStatusReady = !loadingStatusText.empty();
}

