void StepContext()
{
  if(!timerUpdated)
    NMainLoop::UpdateTime();

  if( !NMainFrame::IsExit() )
  {
    NI_PROFILE_BLOCK( "Context" );
    mainPerf_ContextStep.Start();
    context->Poll( NMainLoop::GetTimeDelta() );
    mainPerf_ContextStep.Stop();
  }
  timerUpdated = false;
}

